DROP TABLE IF EXISTS `biens`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `biens` (
  `id_bien` bigint NOT NULL AUTO_INCREMENT,
  `annee_construction` bigint DEFAULT NULL,
  `cave` bit(1) DEFAULT NULL,
  `chambres` int DEFAULT NULL,
  `code_postal` int DEFAULT NULL,
  `commune` varchar(255) DEFAULT NULL,
  `description` varchar(255) DEFAULT NULL,
  `disponibilite` date DEFAULT NULL,
  `disponible` bit(1) DEFAULT NULL,
  `emissionco2` int DEFAULT NULL,
  `energie_specifique` int DEFAULT NULL,
  `energie_totale` int DEFAULT NULL,
  `etages` int DEFAULT NULL,
  `etat` varchar(255) DEFAULT NULL,
  `facades` int DEFAULT NULL,
  `garage` bit(1) DEFAULT NULL,
  `jardin` bit(1) DEFAULT NULL,
  `numero` int DEFAULT NULL,
  `parking` bit(1) DEFAULT NULL,
  `peb` varchar(255) DEFAULT NULL,
  `prix` double DEFAULT NULL,
  `rue` varchar(255) DEFAULT NULL,
  `superficie` double DEFAULT NULL,
  `surface_habitable` int DEFAULT NULL,
  `surface_jardin_terrasse` int DEFAULT NULL,
  `terrasse` bit(1) DEFAULT NULL,
  `title` varchar(255) DEFAULT NULL,
  `type_de_bien` varchar(255) DEFAULT NULL,
  `locataire_id_user` int DEFAULT NULL,
  `proprietaire_id_user` int DEFAULT NULL,
  `type` varchar(255) DEFAULT NULL,
  `salle_de_bain` int DEFAULT NULL,
  `ascenseur` bit(1) DEFAULT NULL,
  `meuble` bit(1) DEFAULT NULL,
  `type_chauffage` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id_bien`),
  UNIQUE KEY `UKqvtb3bowyvexkbogvu4bp3of4` (`locataire_id_user`),
  UNIQUE KEY `UKhetn0cgnuwe3cxu4n5p9iksy7` (`proprietaire_id_user`),
  CONSTRAINT `FK5o32bq112jkqsyo6bsty2etyg` FOREIGN KEY (`proprietaire_id_user`) REFERENCES `users` (`id_user`),
  CONSTRAINT `FKbne0xbfy9alja220xk03c8tjs` FOREIGN KEY (`locataire_id_user`) REFERENCES `users` (`id_user`)
) ENGINE=InnoDB AUTO_INCREMENT=9433 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

